<script setup lang="ts">import type{CrmTicket}from"~/composables/useCrm";defineProps<{items:CrmTicket[];activeId?:string}>();defineEmits<{select:[item:CrmTicket]}>();const label=(state:string)=>({open:"باز",assigned:"در دست بررسی",waiting_customer:"منتظر کاربر",waiting_internal:"منتظر داخلی",resolved:"حل‌شده",closed:"بسته"}[state]??state);</script><template><nav class="crm-queue" aria-label="صف تیکت‌ها"><button v-for="item in items" :key="item.id" type="button" :class="{active:item.id===activeId}" @click="$emit('select',item)"><span><b :data-priority="item.priority">{{item.priority}}</b><i :data-sla="item.sla_state">{{item.sla_state}}</i></span><strong>#{{item.public_id.toLocaleString('fa-IR')}} · {{item.subject}}</strong><small>{{item.display_name||'کاربر'}} · {{label(item.state)}}</small></button></nav></template>
